main.css:
.ts-x-fixed-points-html .lay { position: absolute; inset: 0; display: flex; flex-direction: column; gap: 36px; }
.ts-x-fixed-points-html .head h2 { margin-bottom: 14px; }
.ts-x-fixed-points-html .two { display: grid; grid-template-columns: 1fr 1fr; gap: 72px; align-items: start; }
.ts-x-fixed-points-html h3 { font-family: var(--display); font-size: 26px; line-height: 1.2; font-weight: 500; letter-spacing: -0.015em; margin: 0 0 12px; }
.ts-x-fixed-points-html .fixed { border: 1px solid var(--hair); background: var(--plate); }
.ts-x-fixed-points-html .fixed > div { display: grid; grid-template-columns: 28px 1fr; gap: 18px; align-items: start; padding: 16px 24px; border-bottom: 1px solid var(--hair); }
.ts-x-fixed-points-html .fixed > div:last-child { border-bottom: 0; }
.ts-x-fixed-points-html .fixed .ic { width: 28px; height: 28px; margin-top: 10px; }
.ts-x-fixed-points-html .fixed .name { font-family: var(--display); font-weight: 500; letter-spacing: -0.025em; font-size: 44px; line-height: 1.1; text-wrap: balance; }
.ts-x-fixed-points-html .fixed .names { font-family: var(--display); font-weight: 500; letter-spacing: -0.02em; font-size: 30px; line-height: 1.25; }
.ts-x-fixed-points-html .fixed .names span { white-space: nowrap; }
.ts-x-fixed-points-html .fixed p { margin-top: 8px; font-size: 20px; line-height: 1.45; color: var(--ink-2); }
.ts-x-fixed-points-html .panel { margin-top: 20px; }
.ts-x-fixed-points-html .plain { font-size: 22px; line-height: 1.4; }
.ts-x-fixed-points-html .plain > span { padding: 10px 0; }
